                    row: { "id" => 1, "company_id" => company_id, "locked" => true, "version" => 0 } }],
        links: [{ entry_id: 1, invoice_id: 10, invoice_company_id: company_id, draft: false, discarded: false }],
        invoice_numbers: { 10 => "INV-10" },
        recorded_invoices: {},
        generation: 7,
        captured_at:
      )
    end

    # "Make every derived value repeatable: a reservation's `operation_id` is a UUIDv5 of company, entry
    # and invoice, and timestamps are a capture time passed in."
